function getInitialQuestions() {
  const BANK_VERSION = "selecao-2026-v2";
  const storedVersion = localStorage.getItem("anhanguera_question_bank_version");
  if (storedVersion !== BANK_VERSION) {
    localStorage.removeItem("anhanguera_question_bank");
    localStorage.removeItem("anhanguera_current_exam_state");
    localStorage.setItem("anhanguera_question_bank_version", BANK_VERSION);
    localStorage.setItem("anhanguera_question_bank", JSON.stringify(DEFAULT_QUESTIONS));
    return [...DEFAULT_QUESTIONS];
  }
  const stored = localStorage.getItem("anhanguera_question_bank");
  if (stored) { try { const parsed = JSON.parse(stored); if (Array.isArray(parsed) && parsed.length) return parsed; } catch (e) { console.error("Erro ao carregar banco", e); } }
  localStorage.setItem("anhanguera_question_bank", JSON.stringify(DEFAULT_QUESTIONS));
  return [...DEFAULT_QUESTIONS];
}
